// src/pages/logs/LogsPage.jsx
import React, { useMemo, useState } from 'react';
import { useLogs } from '../../hooks/UseLogs';
import LogFilterBar from '../../components/logs/LogFilterBar';
import LogTable from '../../components/logs/LogTable';
import LogDetailModal from '../../components/logs/LogDetailModal';
import { deleteLog, deleteLogs, exportLogs } from '../../api/LogsApi';

function downloadText(filename, text, mime = 'text/plain;charset=utf-8') {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

function downloadJson(filename, obj) {
  const text = JSON.stringify(obj, null, 2);
  downloadText(filename, text, 'application/json;charset=utf-8');
}

function LogsPage() {
  const { logs, loading, error, limit, setLimit, refresh } = useLogs(50);

  const [keyword, setKeyword] = useState('');
  const [riskFilter, setRiskFilter] = useState('ALL');
  const [selectedLog, setSelectedLog] = useState(null);
  const [selectedIds, setSelectedIds] = useState(() => new Set());

  const handleLimitChange = (e) => {
    const value = Number(e.target.value) || 10;
    setLimit(value);
  };

  const filteredLogs = useMemo(() => {
    const kw = keyword.trim().toLowerCase();
    return (logs || []).filter((log) => {
      const byRisk =
        riskFilter === 'ALL'
          ? true
          : (log.aiLabel || 'UNKNOWN') === riskFilter;

      if (!kw) return byRisk;

      const hay = [
        log.path,
        log.eventType,
        log.aiLabel,
        log.aiDetail,
        String(log.id),
      ]
        .filter(Boolean)
        .join(' ')
        .toLowerCase();

      return byRisk && hay.includes(kw);
    });
  }, [logs, keyword, riskFilter]);

  const toggleSelect = (id) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const toggleSelectAll = () => {
    setSelectedIds((prev) => {
      const all = filteredLogs.map((l) => l.id);
      const allSelected = all.length > 0 && all.every((id) => prev.has(id));
      if (allSelected) return new Set(); // 전체 해제
      return new Set(all); // 전체 선택
    });
  };

  const handleDeleteOne = async (id) => {
    if (!window.confirm(`로그(ID=${id})를 삭제할까요?`)) return;
    await deleteLog(id);
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.delete(id);
      return next;
    });
    setSelectedLog(null);
    refresh();
  };

  const handleDeleteSelected = async () => {
    const ids = Array.from(selectedIds);
    if (ids.length === 0) {
      alert('선택된 로그가 없습니다.');
      return;
    }
    if (!window.confirm(`선택한 로그 ${ids.length}개를 삭제할까요?`)) return;

    await deleteLogs(ids);
    setSelectedIds(new Set());
    setSelectedLog(null);
    refresh();
  };

  const handleExport = async (format) => {
    const ids = Array.from(selectedIds);
    const req = {
      format: format === 'JSON' ? 'JSON' : 'CSV',
      ids: ids.length > 0 ? ids : [],
      // filters는 지금 단계에서는 생략(백엔드 요구 생기면 추가)
    };

    const res = await exportLogs(req);

    if (format === 'JSON') {
      downloadJson(`logs_${Date.now()}.json`, res);
      return;
    }

    // CSV면 text로 옴
    downloadText(`logs_${Date.now()}.csv`, String(res || ''), 'text/csv;charset=utf-8');
  };

  return (
    <div className="page-container">
      <h1>로그 관리</h1>

      <div style={{ display: 'flex', gap: 12, alignItems: 'center', marginBottom: 12 }}>
        <label>
          표시 개수:&nbsp;
          <select value={limit} onChange={handleLimitChange}>
            <option value={10}>10</option>
            <option value={30}>30</option>
            <option value={50}>50</option>
            <option value={100}>100</option>
          </select>
        </label>

        <button className="btn" onClick={() => handleExport('CSV')}>
          CSV 내보내기
        </button>
        <button className="btn" onClick={() => handleExport('JSON')}>
          JSON 내보내기
        </button>

        <button className="btn" onClick={handleDeleteSelected} disabled={selectedIds.size === 0}>
          선택 삭제
        </button>
      </div>

      <LogFilterBar
        keyword={keyword}
        setKeyword={setKeyword}
        riskFilter={riskFilter}
        setRiskFilter={setRiskFilter}
        onRefresh={refresh}
      />

      {loading && <p>로그를 불러오는 중...</p>}
      {error && (
        <p style={{ color: 'red' }}>
          로그를 불러오는 중 오류가 발생했습니다: {error.message}
        </p>
      )}

      {!loading && !error && (
        <LogTable
          logs={filteredLogs}
          onRowClick={(log) => setSelectedLog(log)}
          selectedIds={selectedIds}
          onToggleSelect={toggleSelect}
          onToggleSelectAll={toggleSelectAll}
        />
      )}

      <LogDetailModal
        log={selectedLog}
        onClose={() => setSelectedLog(null)}
        onDelete={() => handleDeleteOne(selectedLog?.id)}
      />
    </div>
  );
}

export default LogsPage;
